  ('g2-s7-fractional_spending_chain-easy-0001', 2, 7, 'fractional_spending_chain', 'easy', '{"start": 40, "den": 5}'::jsonb, 'Kaye had 40 pesos. She spent 1/5 of it. How much money does she have left?', '["32", "24", "8", "40"]'::jsonb, '32', '["gave the amount spent instead of the amount left", "gave the starting amount, forgetting to subtract anything", "subtracted one extra unit''s worth"]'::jsonb, 'She spent 40/5 = 8, leaving 40 - 8 = 32 pesos.', NULL, '', 15, NULL, 'template-mtap-g2-v1', true),
