  ('g2-s7-fractional_spending_chain-average-0001', 2, 7, 'fractional_spending_chain', 'average', '{"start": 24, "den2": 3}'::jsonb, 'Bea had 24 pesos. She spent half of it, then spent 1/3 of what she had left. How much does she have now?', '["8", "20", "24", "12"]'::jsonb, '8', '["stopped after the first spending step, forgot the second", "applied the second fraction to the ORIGINAL amount, not what was left", "gave the starting amount, forgetting to subtract anything"]'::jsonb, 'After spending half: 12 pesos left. After spending 1/3 of that: 12 - 4 = 8 pesos.', NULL, '', 30, NULL, 'template-mtap-g2-v1', true),
